"""Dependency-free, structured reviewer dashboard for synthetic cases."""


def render_reviewer_ui() -> str:
    return r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>Discharge Planning Reviewer</title>
<style>
:root{--ink:#162536;--muted:#627489;--line:#d9e2ec;--page:#f4f7fb;--surface:#fff;--navy:#102f4b;--blue:#1867bc;--blue-soft:#eaf3ff;--green:#0d7a50;--green-soft:#e9f8f1;--amber:#9a6700;--amber-soft:#fff8e5;--red:#b42318;--red-soft:#fff1f0;--radius:12px;--shadow:0 2px 8px rgba(25,49,76,.06)}
*{box-sizing:border-box}body{margin:0;background:var(--page);color:var(--ink);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}header{background:var(--navy);color:#fff;padding:22px max(24px,calc((100vw - 1450px)/2));box-shadow:0 2px 8px rgba(0,0,0,.15)}header h1{margin:0;font-size:27px;letter-spacing:-.4px}header p{margin:4px 0 0;color:#d5e6f5;font-size:13px}main{display:grid;grid-template-columns:310px minmax(0,1fr);gap:18px;max-width:1500px;margin:0 auto;padding:20px}.panel,.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.sidebar{padding:17px;height:max-content;position:sticky;top:16px}.sidebar>h2{font-size:18px;margin:0 0 12px}.divider{border:0;border-top:1px solid var(--line);margin:20px 0}.field-label{display:block;font-weight:650;font-size:13px;margin:12px 0 4px;color:#334e68}.help,.meta{display:block;color:var(--muted);font-size:12px;margin:5px 0 10px}textarea,input,select{font:inherit;width:100%;border:1px solid #b7c6d6;border-radius:7px;background:#fff;padding:9px;outline:none}textarea:focus,input:focus,select:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(24,103,188,.12)}#caseInput{height:160px;resize:vertical;font:12px ui-monospace,SFMono-Regular,Consolas,monospace}.file-input{padding:7px;background:#f8fbff}button{font:inherit;font-weight:650;padding:9px 12px;border:1px solid #b7c6d6;border-radius:7px;background:#fff;color:var(--ink);cursor:pointer;transition:.15s}button:hover{border-color:var(--blue);color:var(--blue);background:#f8fbff}button.primary{background:var(--blue);border-color:var(--blue);color:#fff}button.primary:hover{background:#105aa8;color:#fff}button.danger{color:var(--red)}.button-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.button-row .primary{flex:1}.case{display:block;width:100%;text-align:left;margin:6px 0;padding:10px;border:1px solid var(--line);border-radius:8px;background:#fff}.case:hover{background:var(--blue-soft)}.case b{font-size:13px}.case-state{display:flex;justify-content:space-between;gap:6px;margin-top:3px;color:var(--muted);font-size:12px}.detail-empty{padding:40px;min-height:280px}.detail-empty h2{margin:0 0 8px}.detail-empty p{color:var(--muted);max-width:580px}.case-header{padding:20px;margin-bottom:16px}.case-header h2{margin:0;font-size:24px}.case-header .meta{margin:4px 0 0}.status-grid{display:grid;grid-template-columns:repeat(3,minmax(150px,1fr));gap:10px;margin-top:18px}.status-card{border:1px solid var(--line);border-radius:9px;padding:10px 12px;background:#fbfdff}.status-card dt{text-transform:uppercase;letter-spacing:.45px;font-size:10px;font-weight:750;color:var(--muted)}.status-card dd{margin:4px 0 0;font-weight:720;font-size:14px;overflow-wrap:anywhere}.badge{display:inline-block;border-radius:99px;padding:3px 8px;font-size:12px;font-weight:700}.status-awaiting_review{color:#075a9c;background:var(--blue-soft)}.status-finalized{color:var(--green);background:var(--green-soft)}.status-escalated,.status-rejected{color:var(--red);background:var(--red-soft)}.risk-low{color:var(--green);background:var(--green-soft)}.risk-medium{color:var(--amber);background:var(--amber-soft)}.risk-high{color:var(--red);background:var(--red-soft)}.content-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.card{padding:17px}.card h3{margin:0 0 12px;font-size:16px}.empty{color:var(--muted);font-size:13px;padding:8px 0}.finding{border-left:4px solid var(--amber);padding:10px 11px;margin:8px 0;background:var(--amber-soft);border-radius:0 7px 7px 0}.finding.high{border-color:var(--red);background:var(--red-soft)}.finding.warning{border-color:var(--amber)}.evidence{border-left:4px solid var(--blue);padding:10px 11px;margin:8px 0;background:#f7fbff;border-radius:0 7px 7px 0}.evidence b{display:block}.evidence a,.evidence-ref{color:var(--blue)}.schedule{padding-left:20px;margin:0}.schedule li{margin:10px 0}.schedule small{display:block;color:var(--muted);margin-top:3px}.trace-card,.mapping-card,.editor,.audit-card{margin-top:16px}.trace{list-style:none;padding:0;margin:0}.trace-item{position:relative;display:grid;grid-template-columns:30px 1fr;gap:10px;padding:0 0 13px}.trace-item:not(:last-child):before{content:"";position:absolute;left:12px;top:25px;bottom:0;border-left:2px solid #cbd8e6}.trace-dot{z-index:1;width:25px;height:25px;border-radius:50%;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;font-size:11px;font-weight:750}.trace-main{min-width:0}.trace-title{display:flex;gap:8px;align-items:baseline;flex-wrap:wrap;font-weight:700}.trace-status{font-size:12px;color:var(--blue);font-weight:650}.trace-detail{margin-top:2px;color:var(--muted);font-size:12px;overflow-wrap:anywhere}.trace-time{font-size:11px;color:var(--muted);margin-left:auto}.mapping-intro{color:var(--muted);font-size:12px;margin:-4px 0 10px}.mapping-row{border:1px solid var(--line);border-radius:8px;padding:10px 11px;margin:8px 0;background:#fbfdff}.mapping-type{display:block;text-transform:uppercase;color:var(--muted);font-size:10px;font-weight:750;letter-spacing:.45px}.claim-text{margin:3px 0 7px}.citation-list{display:flex;gap:5px;flex-wrap:wrap}.citation{display:inline-flex;align-items:center;border:1px solid #b9d4ef;border-radius:99px;padding:2px 7px;background:var(--blue-soft);font-size:11px;text-decoration:none}.citation:hover{border-color:var(--blue)}.unmapped{font-size:12px;color:var(--amber);font-weight:650}.editor textarea{min-height:82px;resize:vertical}.review-actions{padding-top:4px}.audit{white-space:pre-wrap;max-height:230px;overflow:auto;background:#f7f9fb;border:1px solid var(--line);padding:10px;border-radius:7px;font:12px ui-monospace,SFMono-Regular,Consolas,monospace;color:#334e68}.audit-card summary{cursor:pointer;color:var(--muted);font-size:13px}.audit-card details{margin-top:6px}@media(max-width:900px){main{grid-template-columns:1fr}.sidebar{position:static}.content-grid{grid-template-columns:1fr}.status-grid{grid-template-columns:1fr}}@media(max-width:520px){main{padding:12px}header{padding:18px 16px}.status-grid{gap:7px}.case-header{padding:16px}}
</style></head>
<body><header><h1>Discharge Planning Reviewer</h1><p>Synthetic teaching cases only</p></header>
<main><aside class="panel sidebar">
  <h2>New synthetic case</h2>
  <label class="field-label" for="caseFile">Upload JSON file</label>
  <input class="file-input" id="caseFile" type="file" accept=".json,application/json" onchange="selectJsonFile(this)">
  <small class="help" id="fileStatus">No file selected. Choose either a JSON file or paste JSON below, then click Create draft.</small>
  <textarea id="caseInput" aria-label="Paste JSON case" placeholder="Paste one synthetic case JSON here. Leave blank when using file upload."></textarea>
  <div class="button-row"><button class="primary" onclick="submitCase()">Create draft</button><button onclick="clearAllInput()">Clear</button></div>
  <hr class="divider"><h2>Cases</h2>
  <label class="field-label" for="filter">Risk filter</label><select id="filter" onchange="loadCases()"><option value="">All risks</option><option value="high">High risk</option><option value="medium">Medium risk</option><option value="low">Low risk</option></select>
  <div id="cases" aria-live="polite"></div>
</aside>
<section id="detail"><div class="panel detail-empty"><h2>Select or create a case</h2><p>Upload one synthetic JSON file or paste one JSON case, then choose <b>Create draft</b>. The agent will validate the case, retrieve approved evidence, construct a medication schedule, run safety checks, and request clinician or pharmacist review when appropriate.</p></div></section></main>
<script>
let active=null,uploadedFileText=null,uploadedFileName=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=url=>typeof url==='string'&&url.startsWith('https://')?url:'';
const evidenceKey=id=>'evidence-'+String(id||'unknown').replace(/[^a-zA-Z0-9_-]/g,'-');
async function api(url,opt){const r=await fetch(url,opt);const d=await r.json();if(!r.ok)throw Error(d.detail||JSON.stringify(d));return d}
function riskBadge(risk){return `<span class="badge risk-${esc(risk||'low')}">${esc(risk||'not assessed')}</span>`}
function statusBadge(status){return `<span class="badge status-${esc(status||'awaiting_review')}">${esc(status||'unknown')}</span>`}
async function loadCases(){const all=await api('/cases');const filter=document.getElementById('filter').value;const items=all.filter(x=>!filter||x.risk_level===filter);document.getElementById('cases').innerHTML=items.map(x=>`<button class="case" onclick="openCase('${x.case_id}')"><b>${esc(x.patient_id||x.case_id.slice(0,8))}</b><span class="case-state"><span>${esc(x.workflow_status)}</span>${riskBadge(x.risk_level)}</span></button>`).join('')||'<p class="empty">No matching cases.</p>'}
async function openCase(id){active=await api('/cases/'+id);render(active);loadCases()}
function evidence(items){return (items||[]).map(x=>{const url=safeUrl(x.source_url);return `<div class="evidence" id="${evidenceKey(x.evidence_id)}"><b>${esc(x.title||x.medication_name||x.tool||'Evidence')}</b><span class="meta">${esc(x.evidence_id||x.source||x.status||'')} ${url?`· <a target="_blank" rel="noopener" href="${esc(url)}">Open source</a>`:''}</span><div>${esc(x.content||x.review_scope||'')}</div></div>`}).join('')||'<p class="empty">No evidence returned.</p>'}
function lines(a){return (a||[]).map(esc).join('\n')}
const traceLabels={receive_case:'Case received',validate_case:'Input validation',construct_patient_state:'Patient state constructed',enrich_medications_with_external_evidence:'Public medication evidence tool',retrieve_knowledge:'Approved knowledge retrieval',generate_discharge_instructions:'Education draft generation',generate_medication_and_followup:'Medication and follow-up tools',safety_check:'Deterministic safety check',request_human_review:'Human review requested',human_review:'Reviewer decision recorded',apply_reviewer_edits:'Reviewer edits applied',finalize_discharge_plan:'Final discharge plan created',reject_discharge_plan:'Plan rejected',escalate_to_clinician:'Escalated to clinician'};
function traceDetail(event){const entries=Object.entries(event||{}).filter(([key])=>!['node','status','timestamp'].includes(key));return entries.map(([key,value])=>`${key.replaceAll('_',' ')}: ${typeof value==='object'?JSON.stringify(value):value}`).join(' · ')}
function trace(events){return (events||[]).map((event,index)=>{const time=event.timestamp?new Date(event.timestamp).toLocaleString():'';return `<li class="trace-item"><span class="trace-dot">${index+1}</span><div class="trace-main"><div class="trace-title"><span>${esc(traceLabels[event.node]||event.node||'Workflow event')}</span><span class="trace-status">${esc(event.status||'completed')}</span><time class="trace-time">${esc(time)}</time></div><div class="trace-detail">${esc(traceDetail(event))}</div></div></li>`}).join('')||'<p class="empty">No workflow events recorded.</p>'}
function claimMappings(s){const evidenceById=Object.fromEntries((s.retrieved_evidence||[]).map(item=>[item.evidence_id,item]));const groups=[['Care instruction',s.discharge_instructions?.care_instructions||[],s.discharge_instructions?.care_instruction_evidence||[]],['Warning note',s.discharge_instructions?.warning_notes||[],s.discharge_instructions?.warning_note_evidence||[]]];const rows=[];for(const [label,claims,mappings] of groups){claims.forEach((claim,index)=>{const ids=mappings[index]||[];const citations=ids.length?ids.map(id=>{const item=evidenceById[id];return `<a class="citation" href="#${evidenceKey(id)}" title="${esc(item?.title||id)}">${esc(id)}</a>`}).join(''):'<span class="unmapped">No approved evidence link. Reviewer confirmation required.</span>';rows.push(`<div class="mapping-row"><span class="mapping-type">${esc(label)} ${index+1}</span><div class="claim-text">${esc(claim)}</div><div class="citation-list">${citations}</div></div>`)});}return rows.join('')||'<p class="empty">No generated claims.</p>'}
function render(record){const s=record.state,pending=record.workflow_status==='awaiting_review';const findings=(s.safety_findings||[]).map(f=>`<div class="finding ${esc(f.severity)}"><b>${esc(f.code)}</b><br>${esc(f.message)}<br><span class="meta">Required action: ${esc(f.required_action)}</span></div>`).join('')||'<p class="empty">No findings.</p>';const schedule=(s.medication_schedule||[]).map(x=>`<li><b>${esc(x.discharge_action)} ${esc(x.medication_name)}</b><br>${esc(x.reminder)}<small>Source fields: ${esc((x.source_fields||[]).join(', '))} · RxCUI: ${esc(x.rxnorm_cui||'unconfirmed')}</small></li>`).join('')||'<p class="empty">No discharge medications.</p>';document.getElementById('detail').innerHTML=`<div class="panel case-header"><h2>${esc(s.patient_id)}</h2><span class="meta">Review the draft against the source data and evidence before making a decision.</span><dl class="status-grid"><div class="status-card"><dt>Workflow status</dt><dd>${statusBadge(record.workflow_status)}</dd></div><div class="status-card"><dt>Risk level</dt><dd>${riskBadge(s.risk_level)}</dd></div><div class="status-card"><dt>Draft generator</dt><dd>${esc(s.discharge_instructions?.generator||'-')}</dd></div></dl></div><div class="panel card trace-card"><h3>Agent workflow trace</h3><p class="mapping-intro">Visible state transitions and tool activity for this case.</p><ol class="trace">${trace(s.audit_log)}</ol></div><div class="content-grid"><div class="card"><h3>Safety findings</h3>${findings}</div><div class="card"><h3>Medication schedule <span class="meta">read-only</span></h3><ul class="schedule">${schedule}</ul></div><div class="card"><h3>Approved local evidence</h3>${evidence(s.retrieved_evidence)}</div><div class="card"><h3>Public drug evidence</h3>${evidence(s.external_drug_evidence)}</div></div><div class="panel card mapping-card"><h3>Evidence-to-claim mapping</h3><p class="mapping-intro">Each generated education statement links to the approved evidence used to support it. Changed reviewer text is deliberately shown as requiring confirmation.</p>${claimMappings(s)}</div><div class="panel card editor"><h3>Editable education draft</h3><label class="field-label">Care instructions <span class="meta">one per line</span><textarea id="care">${lines(s.discharge_instructions?.care_instructions)}</textarea></label><label class="field-label">Warnings <span class="meta">one per line</span><textarea id="warnings">${lines(s.discharge_instructions?.warning_notes)}</textarea></label><label class="field-label">Follow-up tasks <span class="meta">must remain clinician-provided</span><textarea id="followups">${lines(s.follow_up_tasks)}</textarea></label><span class="help">If you change education text, the original evidence mapping is removed for that line and the case returns for review.</span><div class="button-row review-actions">${pending?`<button onclick="decision('edit')">Apply edits and recheck</button><button class="primary" onclick="decision('approve')">Approve</button><button class="danger" onclick="decision('reject')">Reject</button><button class="danger" onclick="decision('escalate')">Escalate</button>`:'<span class="empty">This case is no longer awaiting a reviewer decision.</span>'}</div></div><div class="panel card audit-card"><details><summary>View raw audit records</summary><pre class="audit">${esc(JSON.stringify(s.audit_log||[],null,2))}</pre></details></div>`}
function renderExportActions(record){if(record.workflow_status!=='finalized')return;const patient=record.state.patient_id||'synthetic-case';document.getElementById('detail').insertAdjacentHTML('beforeend',`<div class="panel card" style="margin-top:16px"><h3>Approved plan exports</h3><p class="mapping-intro">Downloads are available only after an explicit reviewer approval.</p><div class="button-row"><button class="primary" onclick="downloadExport('json')">Download final plan JSON</button><button onclick="downloadExport('fhir')">Download FHIR R4 Bundle</button></div></div>`)}
async function downloadExport(format){if(!active||active.workflow_status!=='finalized')return;const path=format==='fhir'?'fhir-r4-bundle.json':'final-plan.json';try{const response=await fetch(`/cases/${active.case_id}/export/${path}`);if(!response.ok){const body=await response.json();throw Error(body.detail||'Export failed')}const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${String(active.state.patient_id||'synthetic-case').replace(/[^a-zA-Z0-9_-]/g,'-')}_${format==='fhir'?'fhir-r4-bundle':'final-plan'}.json`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),0)}catch(error){alert('Unable to export: '+error.message)}}
const renderCaseDetail=render;
render=function(record){renderCaseDetail(record);renderExportActions(record)};
function array(id){return document.getElementById(id).value.split('\n').map(x=>x.trim()).filter(Boolean)}
async function decision(decision){if(!active)return;const reviewer_id=prompt('Reviewer ID','demo-clinician');if(!reviewer_id)return;const reviewer_role=prompt('Role: clinician or pharmacist','clinician');if(!['clinician','pharmacist'].includes(reviewer_role)){alert('Role must be clinician or pharmacist');return}const body={decision,reviewer_id,reviewer_role,notes:'Dashboard decision'};if(decision==='edit')body.edits={care_instructions:array('care'),warning_notes:array('warnings'),follow_up_tasks:array('followups')};try{const r=await api(`/cases/${active.case_id}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});active={case_id:r.case_id,workflow_status:r.workflow_status,state:r.state};render(active);loadCases()}catch(e){alert(e)}}
async function createCase(c){const r=await api('/cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({case:c})});active={case_id:r.case_id,workflow_status:r.workflow_status,state:r.state};render(active);loadCases()}
function clearFileSelection(){uploadedFileText=null;uploadedFileName=null;document.getElementById('caseFile').value='';document.getElementById('fileStatus').textContent='No file selected. Choose either a JSON file or paste JSON below, then click Create draft.'}
function clearAllInput(){document.getElementById('caseInput').value='';clearFileSelection()}
async function selectJsonFile(input){const file=input.files?.[0];if(!file)return;const textInput=document.getElementById('caseInput');if(textInput.value.trim()){alert('Use only one input method. Clear pasted JSON before selecting a file.');input.value='';return}if(!file.name.toLowerCase().endsWith('.json')){alert('Please choose a .json file.');input.value='';return}try{uploadedFileText=await file.text();uploadedFileName=file.name;document.getElementById('fileStatus').textContent=`Selected: ${file.name}. Click Create draft to submit it.`}catch(e){clearFileSelection();alert('Unable to read JSON file: '+e)}}
async function submitCase(){const text=document.getElementById('caseInput').value.trim();const hasText=Boolean(text),hasFile=Boolean(uploadedFileText);if(hasText&&hasFile){alert('Use only one input method: clear pasted JSON or remove the selected file.');return}if(!hasText&&!hasFile){alert('Paste one synthetic JSON case or select one JSON file first.');return}try{const c=JSON.parse(hasFile?uploadedFileText:text);await createCase(c);clearAllInput()}catch(e){alert('Unable to create case: '+e)}}
loadCases();
</script></body></html>"""
